import { readFile } from "node:fs/promises";
import path from "node:path";
import { createClient } from "@supabase/supabase-js";
import { NextResponse } from "next/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const responseHeaders = {
  "Cache-Control": "private, no-store, max-age=0",
  "X-Content-Type-Options": "nosniff",
  Vary: "Authorization",
};

/**
 * Returns private reference HTML only after Supabase verifies the bearer token.
 * An explicit edition allowlist prevents filesystem traversal; content is never cached.
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ edition: string }> },
) {
  const { edition } = await params;
  if (edition !== "summary" && edition !== "detailed") {
    return NextResponse.json(
      { error: "Reference edition not found." },
      { status: 404, headers: responseHeaders },
    );
  }

  const authorization = request.headers.get("authorization");
  const token = authorization?.match(/^Bearer (\S+)$/)?.[1];
  if (!token) {
    return NextResponse.json(
      { error: "Sign in to read the Life Reference Book." },
      { status: 401, headers: responseHeaders },
    );
  }

  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
  if (!url || !key) {
    console.error("Life reference: Supabase configuration is missing.");
    return NextResponse.json(
      { error: "Reference service is not configured." },
      { status: 500, headers: responseHeaders },
    );
  }

  try {
    const supabase = createClient(url, key, {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    });
    const { data, error } = await supabase.auth.getUser(token);
    if (error || !data.user) {
      const unavailable = error && (!error.status || error.status >= 500);
      if (unavailable) {
        console.error("Life reference: session verification failed.", {
          code: error.code,
          status: error.status,
        });
      }
      return NextResponse.json(
        { error: unavailable ? "Unable to verify your session. Try again." : "Your session is invalid or expired. Sign in again." },
        { status: unavailable ? 503 : 401, headers: responseHeaders },
      );
    }

    const html = await readFile(
      path.join(process.cwd(), "src", "content", "life-reference", `${edition}.html`),
      "utf8",
    );
    return NextResponse.json({ html }, { headers: responseHeaders });
  } catch (error) {
    console.error(
      "Life reference: content request failed.",
      error instanceof Error ? error.message : "Unknown error",
    );
    return NextResponse.json(
      { error: "Unable to load the Life Reference Book. Try again." },
      { status: 503, headers: responseHeaders },
    );
  }
}
